export const VALIDATION_JS = "(function(){\n\tfunction ready(fn){ if(document.readyState!==\"loading\"){fn();} else {document.addEventListener(\"DOMContentLoaded\",fn);} }\n\tready(function(){\n\t\tvar form = document.getElementById(\"gff-reg-form\");\n\t\tif(!form){return;}\n\t\tfunction isSectionComplete(group){\n\t\t\tif(group.getAttribute(\"data-gff-section\")===\"crops\"){\n\t\t\t\treturn Array.from(group.querySelectorAll(\"input[name='gff_crops[]']\")).some(function(c){return c.checked;});\n\t\t\t}\n\t\t\tvar inputs = group.querySelectorAll(\"input[required]\");\n\t\t\tif(inputs.length===0){return true;}\n\t\t\tfor(var i=0;i<inputs.length;i++){\n\t\t\t\tvar inp=inputs[i];\n\t\t\t\tif(inp.type===\"checkbox\"){\n\t\t\t\t\tif(!inp.checked){return false;}\n\t\t\t\t} else if(inp.type===\"password\" && inp.name===\"gff_pass2\"){\n\t\t\t\t\tvar pass1=form.querySelector(\"input[name='gff_pass']\");\n\t\t\t\t\tif(!pass1 || pass1.value.length<8 || inp.value!==pass1.value){return false;}\n\t\t\t\t} else if(inp.type===\"password\"){\n\t\t\t\t\tif(inp.value.length<8){return false;}\n\t\t\t\t} else if(inp.type===\"email\"){\n\t\t\t\t\tif(!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(inp.value)){return false;}\n\t\t\t\t} else if(!(inp.value||\"\").trim()){\n\t\t\t\t\treturn false;\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn true;\n\t\t}\n\t\tfunction update(){\n\t\t\tvar groups=form.querySelectorAll(\".gff-reg__group[data-gff-required='1']\");\n\t\t\tgroups.forEach(function(g){\n\t\t\t\tg.setAttribute(\"data-gff-complete\", isSectionComplete(g)?\"yes\":\"no\");\n\t\t\t});\n\t\t}\n\t\tform.querySelectorAll(\".gff-reg__group[data-gff-required='1']\").forEach(function(g){\n\t\t\tg.setAttribute(\"data-gff-complete\",\"no\");\n\t\t});\n\t\tform.addEventListener(\"input\", update);\n\t\tform.addEventListener(\"change\", update);\n\t\tform.addEventListener(\"submit\", function(e){\n\t\t\tupdate();\n\t\t\tvar firstIncomplete=form.querySelector(\".gff-reg__group[data-gff-required='1'][data-gff-complete='no']\");\n\t\t\tif(firstIncomplete){\n\t\t\t\te.preventDefault();\n\t\t\t\tfirstIncomplete.scrollIntoView({behavior:\"smooth\", block:\"center\"});\n\t\t\t\tfirstIncomplete.classList.add(\"gff-shake\");\n\t\t\t\tsetTimeout(function(){firstIncomplete.classList.remove(\"gff-shake\");},600);\n\t\t\t}\n\t\t});\n\t\tupdate();\n\t\tvar sqft=form.querySelector(\"#gff_sqft\");\n\t\tvar est=form.querySelector(\"#gff_est\");\n\t\tvar val=form.querySelector(\"#gff_est_val\");\n\t\tvar note=form.querySelector(\"#gff_est_text\");\n\t\tif(sqft){\n\t\t\tsqft.addEventListener(\"input\",function(){\n\t\t\t\tvar raw=(sqft.value||\"\").trim();\n\t\t\t\tvar isNum=raw!==\"\" && /^[0-9]+(\\.[0-9]+)?$/.test(raw);\n\t\t\t\tif(isNum){\n\t\t\t\t\tvar n=parseFloat(raw);\n\t\t\t\t\tif(n<=0){ if(est)est.hidden=true; if(note)note.hidden=true; }\n\t\t\t\t\telse if(n<=1500){ if(val)val.textContent=n+\" sq ft included\"; if(est)est.hidden=false; if(note)note.hidden=true; }\n\t\t\t\t\telse { if(val)val.textContent=n+\" sq ft (larger than one module — we will discuss multi-module options)\"; if(est)est.hidden=false; if(note)note.hidden=true; }\n\t\t\t\t} else { if(est)est.hidden=true; if(note)note.hidden=(raw===\"\"); }\n\t\t\t});\n\t\t}\n\t});\n})();";
export const ZORA_DISPLAY_T = "\t<section class=\"gff-zora-display\">\n\t\t<div>\n\t\t\t<header class=\"gff-zora-display__head\">\n\t\t\t\t<h2 class=\"gff-zora-display__title\">The Zora Sunrise Module<sup>&trade;</sup></h2>\n\t\t\t\t<p class=\"gff-zora-display__sub\">A complete food forest, installed on your property.</p>\n\t\t\t</header>\n\t\t\t<div class=\"gff-zora-display__viz\">\n\t\t\t\t<svg viewBox=\"0 0 500 280\" xmlns=\"http://www.w3.org/2000/svg\" preserveAspectRatio=\"xMidYMid meet\">\n\t\t\t\t\t<defs><filter id=\"zoraBlend\" x=\"-5%\" y=\"-5%\" width=\"110%\" height=\"110%\"><feGaussianBlur in=\"SourceGraphic\" stdDeviation=\"6\"/></filter></defs>\n\t\t\t\t\t<text x=\"20\" y=\"28\" class=\"zlbl\">&#x2191; N</text>\n\t\t\t\t\t<text x=\"480\" y=\"28\" text-anchor=\"end\" class=\"zlbl\">44 ft &times; 22 ft</text>\n\t\t\t\t\t<g filter=\"url(#zoraBlend)\">\n\t\t\t\t\t\t<path d=\"M 40 60 A 210 210 0 0 0 460 60 L 404 60 A 154 154 0 0 1 96 60 Z\" fill=\"#D4B5E8\"/>\n\t\t\t\t\t\t<path d=\"M 96 60 A 154 154 0 0 0 404 60 L 352 60 A 102 102 0 0 1 148 60 Z\" fill=\"#F5A8A0\"/>\n\t\t\t\t\t\t<path d=\"M 148 60 A 102 102 0 0 0 352 60 L 308 60 A 58 58 0 0 1 192 60 Z\" fill=\"#FBE38A\"/>\n\t\t\t\t\t\t<path d=\"M 192 60 A 58 58 0 0 0 308 60 L 280 60 A 30 30 0 0 1 220 60 Z\" fill=\"#D4B5E8\"/>\n\t\t\t\t\t\t<circle cx=\"250\" cy=\"80\" r=\"28\" fill=\"#A8D5A0\"/>\n\t\t\t\t\t\t<circle cx=\"198\" cy=\"78\" r=\"18\" fill=\"#A8C8E8\"/>\n\t\t\t\t\t\t<circle cx=\"302\" cy=\"78\" r=\"18\" fill=\"#A8C8E8\"/>\n\t\t\t\t\t</g>\n\t\t\t\t\t<path d=\"M 40 60 A 210 210 0 0 0 460 60 Z\" fill=\"none\" stroke=\"#9b9387\" stroke-width=\"1\"/>\n\t\t\t\t\t<line x1=\"40\" y1=\"60\" x2=\"460\" y2=\"60\" stroke=\"#5F5E5A\" stroke-width=\"1.5\"/>\n\t\t\t\t</svg>\n\t\t\t</div>\n\t\t\t<ul class=\"gff-zora-display__legend\">\n\t\t\t\t<li><span class=\"zsw\" style=\"background:#A8D5A0\"></span>Moringa <em>&middot; canopy anchor</em></li>\n\t\t\t\t<li><span class=\"zsw\" style=\"background:#A8C8E8\"></span>Pigeon pea <em>&middot; nitrogen-fixers</em></li>\n\t\t\t\t<li><span class=\"zsw\" style=\"background:#D4B5E8\"></span>Longevity spinach <em>&middot; perennial spreader</em></li>\n\t\t\t\t<li><span class=\"zsw\" style=\"background:#FBE38A\"></span>Hot greens <em>&middot; year-round</em></li>\n\t\t\t\t<li><span class=\"zsw\" style=\"background:#F5A8A0\"></span>Seasonal block <em>&middot; rotates twice yearly</em></li>\n\t\t\t\t<li><span class=\"zsw\" style=\"background:#D4B5E8\"></span>Sweet potato carpet <em>&middot; ground-layer spreader</em></li>\n\t\t\t</ul>\n\t\t</div>\n\t</section>\n\t";
export const EXPRESS_START_T = "@@NOTICE@@\t<div class=\"gff-reg gff-reg--express\">\n\t\t<form class=\"gff-reg__form\" method=\"post\" novalidate id=\"gff-express-form\">\n\t\t\t<input type=\"hidden\" id=\"gff_express_nonce\" name=\"gff_express_nonce\" value=\"nonce-gff_express_action\" /><input type=\"hidden\" name=\"_wp_http_referer\" value=\"@@REFERER@@\" />\t\t\t<input type=\"hidden\" name=\"gff_offer\" id=\"gff_offer_field_x\" value=\"\">\n\t\t\t<div class=\"gff-hp\" aria-hidden=\"true\">\n\t\t\t\t<label>Company URL <input type=\"text\" name=\"gff_company_url\" tabindex=\"-1\" autocomplete=\"off\"></label>\n\t\t\t</div>\n\t";
export const EXPRESS_EMAIL_T = "\t<fieldset class=\"gff-reg__group gff-express-email\" data-gff-section=\"express-email\">\n\t\t<legend>@@LEGEND@@</legend>\n\t\t<label class=\"gff-express-email__label\">@@LABEL@@\t\t\t<input type=\"email\" name=\"gff_email\"@@VAL@@ required placeholder=\"you@email.com\">\n\t\t</label>\n\t\t<p class=\"gff-express-email__note\">That&rsquo;s all we need to hold your spot. You can add the rest now or after.</p>\n\t</fieldset>\n\t";
export const CONSULT_T = "\t<fieldset class=\"gff-reg__group gff-consult\" data-gff-section=\"consult\">\n\t\t<legend>@@LEGEND@@</legend>\n\t\t<input type=\"hidden\" name=\"gff_reservation\" value=\"consult\">\n\t\t<div class=\"gff-consult__opt gff-consult__opt--only\">\n\t\t\t<span class=\"gff-consult__opt-body\">\n\t\t\t\t<strong>$250 &mdash; your design consult</strong>\n\t\t\t\t<em>We come out, measure light, water, and drainage, stake the corners of your farm, photograph the site, and sit down to find out what your family actually eats. <strong>Credited in full</strong> toward your design, build, and install. Non-refundable &mdash; if we walk your property and it isn&rsquo;t a fit, you keep the design.</em>\n\t\t\t</span>\n\t\t</div>\n\t\t<p class=\"gff-consult__paylater\">$772 to start &mdash; consultation, design, build, install, your first month of service, and the Propagation Program. The $250 consult is credited in full, leaving <strong>$522</strong> due at install. Then $300/month, and it never goes up.</p>\n\t\t<p class=\"gff-consult__paylater\">After you submit, the success page shows your PayPal link for the $250 design consult.</p>\n\t</fieldset>\n\t";
export const THREE_SISTERS_T = "\t<div class=\"gff-ts-field\">\n\t\t<p class=\"gff-ts-note\">\n\t\t\t🌽 <strong>The Propagation Program is included.</strong> After your first year &mdash; and every year after &mdash;\n\t\t\tyour farm propagates a free Spire tower, yours to keep, free to service. We also install a free Sunrise module\n\t\t\tfor a family that couldn&rsquo;t afford one. No charge, no opt-in, and your monthly rate never changes.\n\t\t</p>\n\t</div>\n\t";
export const AGREEMENT_T = "\t<fieldset class=\"gff-reg__group\" data-gff-section=\"agreement\" data-gff-required=\"1\">\n\t\t<details class=\"gff-acc-wrap\">\n\t\t\t<summary class=\"gff-acc-wrap__summary\">Service Agreement <span class=\"gff-acc-wrap__hint\">(tap to read)</span><span class=\"gff-acc__chev\" aria-hidden=\"true\"></span></summary>\n\t\t\t<div class=\"gff-acc\">\n\t\t\t\t<p style=\"font-weight:700;color:#1c1c1a;margin:12px 0 4px;\">&#127749; Zora Sunrise Module</p>\n\t\t\t\t\t\t\t\t\t<details class=\"gff-acc__item\" open>\n\t\t\t\t\t\t<summary>1. Services Provided<span class=\"gff-acc__chev\" aria-hidden=\"true\"></span></summary>\n\t\t\t\t\t\t<div class=\"gff-acc__body\"><p>Provider agrees to design, install, and maintain a permaculture-based food and flower garden system on the Customer&#039;s property (the &quot;System&quot;), known as The Zora Sunrise Module™. Services include site assessment, custom system design, installation, planting, soil biology, mulching, and ongoing maintenance visits as scheduled.</p></div>\n\t\t\t\t\t</details>\n\t\t\t\t\t\t\t\t\t<details class=\"gff-acc__item\">\n\t\t\t\t\t\t<summary>2. Pricing &amp; Monthly Service<span class=\"gff-acc__chev\" aria-hidden=\"true\"></span></summary>\n\t\t\t\t\t\t<div class=\"gff-acc__body\"><p>Monthly service is $300 per month, flat, for either offer or both. The fee covers design, installation, planting, materials, soil biology, maintenance, seasonal replanting, and system management, including maintenance of any additional Spires added under the Propagation Program at no additional charge. For The Zora Sunrise Module™, Provider will install the largest module the property reasonably allows up to 1,500 sq ft; module size does not affect price. Gawlak Family Farms guarantees a minimum of $300 per month in food harvest value once the system reaches steady production (typically by month 3), calculated using current Treasure Coast farmers market retail prices. Harvest value is measured by what the system produces, not by what the Customer harvests; produce left unharvested counts toward the guarantee. Monthly fees are due on the 1st. THE MONTHLY FEE WILL NOT INCREASE FOR THE DURATION OF CONTINUOUS SERVICE. No rate-lock election is required; this is a term of this Agreement.</p></div>\n\t\t\t\t\t</details>\n\t\t\t\t\t\t\t\t\t<details class=\"gff-acc__item\">\n\t\t\t\t\t\t<summary>3. Land Access, License to Tend &amp; Right to Harvest<span class=\"gff-acc__chev\" aria-hidden=\"true\"></span></summary>\n\t\t\t\t\t\t<div class=\"gff-acc__body\"><p>(a) Grant of License. Customer, as owner or lawful possessor of the Property at the Service Address, grants Gawlak Family Farms a non-exclusive, revocable license to enter, access, and use the designated Garden Area solely to design, install, maintain, and harvest from the System. This license creates no leasehold, easement, or other real-property interest. (b) Scope of Access. Access is limited to the Garden Area and reasonable pathways to reach it, during reasonable hours and with reasonable notice, except for emergency maintenance to protect the System or Property. (c) No Trespass; Indemnification. Execution of this Agreement constitutes consent to the access described and waives any trespass claim arising from authorized entry. Each party indemnifies the other as set out in the full Agreement. (d) Termination of License. The license terminates automatically upon expiration or termination of the Agreement, at which point Provider&#039;s access rights immediately cease.</p></div>\n\t\t\t\t\t</details>\n\t\t\t\t\t\t\t\t\t<details class=\"gff-acc__item\">\n\t\t\t\t\t\t<summary>4. Term &amp; Changes<span class=\"gff-acc__chev\" aria-hidden=\"true\"></span></summary>\n\t\t\t\t\t\t<div class=\"gff-acc__body\"><p>This enrollment begins on the agreed Start Date and continues month-to-month unless a fixed term is agreed in writing. Either party may end the arrangement with 30 days written notice. This online enrollment records the Customer&#039;s acceptance; the full executed Service Agreement governs the relationship.</p></div>\n\t\t\t\t\t</details>\n\t\t\t\t\t\t\t\t\t<details class=\"gff-acc__item\">\n\t\t\t\t\t\t<summary>5. Getting Started — Design Consult &amp; Starter Cost<span class=\"gff-acc__chev\" aria-hidden=\"true\"></span></summary>\n\t\t\t\t\t\t<div class=\"gff-acc__body\"><p>The total starter cost is $772, covering the professional consultation, custom design, build, installation, the Customer&#039;s first month of service, complimentary herb sections, enrollment in the Propagation Program, and one apparel item. (a) DESIGN CONSULT — $250. Payable at enrollment via PayPal. Provider attends the Property to assess light, water, drainage, and constraints; stakes or marks the footprint; photographs the site; and works with the Customer to determine planting preferences. The $250 is NON-REFUNDABLE but is CREDITED IN FULL toward the Customer&#039;s design, build, and install. An on-site design consult is available only with this payment. If Provider determines the Property is not suitable, or the Customer elects not to proceed, the Customer retains the design and the $250 is retained by Provider as compensation for the assessment and design work performed. (b) BALANCE — $522, due at install. (c) The starter cost includes the Customer&#039;s first month of service. The system requires approximately one month to reach initial production; the Customer does not pay a monthly fee for that period. Monthly billing begins in month two.</p></div>\n\t\t\t\t\t</details>\n\t\t\t\t\t\t\t\t\t\t\t\t\t<p style=\"font-weight:700;color:#1c1c1a;margin:16px 0 4px;\">&#9889; Spire Towers</p>\n\t\t\t\t\t\t\t\t\t\t\t<details class=\"gff-acc__item\">\n\t\t\t\t\t\t\t<summary>1. Services Provided<span class=\"gff-acc__chev\" aria-hidden=\"true\"></span></summary>\n\t\t\t\t\t\t\t<div class=\"gff-acc__body\"><p>Provider agrees to supply, install, and maintain one or more vertical tower growing systems (each a &quot;Spire,&quot; collectively the &quot;System&quot;) at the Customer&#039;s property, known as Spire Towers by Gawlak Family Farms. Services include site assessment, placement for sun and water, tower assembly and installation, planting, soil and nutrient management, and ongoing maintenance visits as scheduled. Each Spire includes a base herb garden section at no additional charge.</p></div>\n\t\t\t\t\t\t</details>\n\t\t\t\t\t\t\t\t\t\t\t<details class=\"gff-acc__item\">\n\t\t\t\t\t\t\t<summary>2. Pricing &amp; Monthly Service<span class=\"gff-acc__chev\" aria-hidden=\"true\"></span></summary>\n\t\t\t\t\t\t\t<div class=\"gff-acc__body\"><p>Monthly service is $300 per month for three (3) Spire Towers. Setup and installation are included in the starter cost. Each Spire includes a complimentary herb section at its base; herb sections are excluded from any food-value calculation. Spires installed under the Propagation Program are serviced at no additional monthly charge. Monthly fees are due on the 1st, and are invoiced by Provider. THE MONTHLY FEE WILL NOT INCREASE FOR THE DURATION OF CONTINUOUS SERVICE. No rate-lock election is required; this is a term of this Agreement.</p></div>\n\t\t\t\t\t\t</details>\n\t\t\t\t\t\t\t\t\t\t\t<details class=\"gff-acc__item\">\n\t\t\t\t\t\t\t<summary>3. Equipment Ownership<span class=\"gff-acc__chev\" aria-hidden=\"true\"></span></summary>\n\t\t\t\t\t\t\t<div class=\"gff-acc__body\"><p>(a) Ownership During Term. All Spire tower units, growing components, pumps, and associated equipment are and remain the sole property of Gawlak Family Farms during the term of this Agreement. The monthly fee is for the service and use of the System and does not, by itself, transfer ownership to the Customer. (b) Ownership at Two-Year Completion. If the Customer completes a two-year (24-month) term of continuous service, ownership of the installed Spire tower units transfers to the Customer at the end of that term, at no additional charge. Until the two-year term is completed, the Spires remain the property of Gawlak Family Farms. (c) Removal on Early Termination. If this Agreement ends for any reason before the two-year term is completed, Gawlak Family Farms retains ownership and may enter the property on reasonable notice to recover and remove its tower units and equipment. Plantings and harvestable produce present at the time of removal are the Customer&#039;s to keep. (d) Care. Customer agrees not to relocate, dismantle, sell, or alter Spire tower units that remain Provider property, and to provide reasonable protection against avoidable damage, normal weather and growing conditions excepted.</p></div>\n\t\t\t\t\t\t</details>\n\t\t\t\t\t\t\t\t\t\t\t<details class=\"gff-acc__item\">\n\t\t\t\t\t\t\t<summary>4. The Propagation Program (Included)<span class=\"gff-acc__chev\" aria-hidden=\"true\"></span></summary>\n\t\t\t\t\t\t\t<div class=\"gff-acc__body\"><p>The Propagation Program is included at no charge and requires no election or additional payment. After twelve (12) months of continuous service, and on each anniversary thereafter, the following occur at no additional charge to the Customer: (a) CUSTOMER SPIRE. One free Spire Tower is installed at the Customer&#039;s Property. It becomes the Customer&#039;s property upon installation and is not subject to the equipment-ownership or removal terms of Section 3. Its maintenance is included in the existing monthly fee, which does not increase. (b) DONATED MODULE. Gawlak Family Farms installs one Zora Sunrise Module, at no cost, for a recipient household selected by Provider. Recipient households are selected by Provider at its sole discretion. The donated module is not assignable, transferable, or redeemable by the Customer for cash, credit, or any other consideration, and the Customer acquires no interest in it. (c) CONTINUITY. Propagation is contingent on continuous service. Service interrupted or terminated before an anniversary forfeits that year&#039;s propagation. (d) SUBSTITUTION. Provider may substitute an equivalent system where site conditions make a Spire unsuitable.</p></div>\n\t\t\t\t\t\t</details>\n\t\t\t\t\t\t\t\t\t\t\t<details class=\"gff-acc__item\">\n\t\t\t\t\t\t\t<summary>5. Land Access &amp; License to Tend<span class=\"gff-acc__chev\" aria-hidden=\"true\"></span></summary>\n\t\t\t\t\t\t\t<div class=\"gff-acc__body\"><p>(a) Grant of License. Customer, as owner or lawful possessor of the property at the Service Address, grants Gawlak Family Farms a non-exclusive, revocable license to enter, access, and use the designated tower location solely to install, maintain, harvest from, and (on termination) remove the System. This license creates no leasehold, easement, or other real-property interest. (b) Scope of Access. Access is limited to the tower location and reasonable pathways to reach it, during reasonable hours and with reasonable notice, except for emergency maintenance to protect the System or property. (c) Termination of License. The license terminates automatically upon expiration or termination of the Agreement, at which point Provider retains only the limited right of entry needed to remove its equipment under Section 3.</p></div>\n\t\t\t\t\t\t</details>\n\t\t\t\t\t\t\t\t\t\t\t<details class=\"gff-acc__item\">\n\t\t\t\t\t\t\t<summary>6. Term &amp; Changes<span class=\"gff-acc__chev\" aria-hidden=\"true\"></span></summary>\n\t\t\t\t\t\t\t<div class=\"gff-acc__body\"><p>Service begins on the agreed Start Date and continues month-to-month. Either party may terminate with thirty (30) days written notice. No fixed-term election is required. Ownership of the installed Spire tower units transfers to the Customer automatically upon completion of twenty-four (24) months of continuous service, as set out in Section 3. Termination before that date forfeits Spire ownership under Section 3 and any pending propagation under Section 4. This online enrollment records the Customer&#039;s acceptance; the full executed Service Agreement governs the relationship.</p></div>\n\t\t\t\t\t\t</details>\n\t\t\t\t\t\t\t\t\t\t\t<details class=\"gff-acc__item\">\n\t\t\t\t\t\t\t<summary>7. Getting Started — Design Consult &amp; Starter Cost<span class=\"gff-acc__chev\" aria-hidden=\"true\"></span></summary>\n\t\t\t\t\t\t\t<div class=\"gff-acc__body\"><p>The total starter cost is $772, covering the professional consultation, custom design, build, installation, the Customer&#039;s first month of service, complimentary herb sections at the base of each Spire, enrollment in the Propagation Program, and one apparel item. (a) DESIGN CONSULT — $250. Payable at enrollment via PayPal. Provider attends the Property to assess light, water, wind, surface, and constraints; marks each Spire footprint; photographs the site; and works with the Customer to determine planting preferences. The $250 is NON-REFUNDABLE but is CREDITED IN FULL toward the Customer&#039;s design, build, and install. An on-site design consult is available only with this payment. If Provider determines the Property is not suitable, or the Customer elects not to proceed, the Customer retains the design and the $250 is retained by Provider as compensation for the assessment and design work performed. (b) BALANCE — $522, due at install. (c) The starter cost includes the Customer&#039;s first month of service. Monthly billing begins in month two.</p></div>\n\t\t\t\t\t\t</details>\n\t\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t</details>\n\t\t@@THREE_SISTERS@@\t\t<label class=\"gff-check\">\n\t\t\t<input type=\"checkbox\" name=\"gff_agree\" value=\"yes\"@@CHECKED@@ required>\n\t\t\t<span>I have read and accept the Gawlak Family Farms Service Agreement (v6.0 (2026-07)) &mdash; covering both the Zora Sunrise Module and Spire Towers.</span>\n\t\t</label>\n\t</fieldset>\n\t";
